/**
 * Stand-in models for the settlement's structure kinds, so the town shows art without the licensed
 * packs (SG4a: "use stand-in placeholders where art blocks work"). Each kind gets one model whose name
 * matches its DEFAULT_ART_PATTERNS entry, so `buildArtMap` maps it exactly as it maps a licensed preset.
 * The GLBs are generated by scripts/gen-placeholder-art.mjs into apps/client/public/placeholder-art/.
 * They are plain boxes: no licensed art, nothing from the packs.
 */

import type { CatalogModel } from "./art.js";

export interface PlaceholderArt {
  /** The structure kind this model stands for (a key of DEFAULT_ART_PATTERNS). */
  kind: string;
  /** The model's name, which the kind's art pattern must match. */
  name: string;
  /** Footprint width, height, depth in metres: the model's own size, not the body's. */
  size: [number, number, number];
}

const BUILDING: [number, number, number] = [6, 5, 6];
const SMALL: [number, number, number] = [4, 1, 4];

