/** The catalog the placeholder GLBs are written with (the same shape the dev server serves for the licensed art). */
export function placeholderCatalog(): { models: CatalogModel[] } {
  return {
    models: PLACEHOLDER_ART.map((p) => ({ id: p.name, name: p.name, skinned: false, size: p.size })),
  };
}
